/// <summary>
/// The store's bins, or what became of a bin or of the counts sent per bin.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountBinResponse
{
    boolean success;
    str errorCode;
    str message;
    int accepted;
    List bins;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('Accepted')]
public int parmAccepted(int _value = accepted)
{
    accepted = _value;
    return accepted;
}

[DataMemberAttribute('Bins')]
public List parmBins(List _value = bins)
{
    bins = _value;
    return bins;
}
